B.aFw=new A.fR("context_translate","\ud83d\udd24","D\u1ecbch c\xf3 ng\u1eef c\u1ea3nh","D\u1ecbch k\xe8m v\u0103n h\xf3a, c\xe1ch d\xf9ng","B\u1ea1n l\xe0 phi\xean d\u1ecbch vi\xean chuy\xean nghi\u1ec7p Vi\u1ec7t-Trung. D\u1ecbch ch\xednh x\xe1c, gi\u1ea3i th\xedch ng\u1eef c\u1ea3nh, c\xe1c c\xe1ch di\u1ec5n \u0111\u1ea1t kh\xe1c, l\u01b0u \xfd v\u0103n h\xf3a. Tr\u1ea3 l\u1eddi b\u1eb1ng ti\u1ebfng Vi\u1ec7t.",B.a7P,B.a7K,!1)
B.a16=s(["So\u1ea1n email xin ngh\u1ec9 ph\xe9p","Gi\u1ea3i th\xedch \u0111i\u1ec1u kho\u1ea3n h\u1ee3p \u0111\u1ed3ng n\xe0y","C\xe1ch n\xf3i chuy\u1ec7n v\u1edbi s\u1ebfp \u0110\xe0i Loan"],t.s)
B.aFD=new A.fR("work","\ud83d\udcbc","C\xf4ng vi\u1ec7c","Email, h\u1ee3p \u0111\u1ed3ng, c\xf4ng s\u1edf","B\u1ea1n l\xe0 tr\u1ee3 l\xfd h\u1ed7 tr\u1ee3 ng\u01b0\u1eddi Vi\u1ec7t l\xe0m vi\u1ec7c \u1edf \u0110\xe0i Loan. Gi\xfap so\u1ea1n email, gi\u1ea3i th\xedch h\u1ee3p \u0111\u1ed3ng, t\u1eeb v\u1ef1ng c\xf4ng s\u1edf, c\xe1ch giao ti\u1ebfp chuy\xean nghi\u1ec7p. Tr\u1ea3 l\u1eddi b\u1eb1ng ti\u1ebfng Vi\u1ec7t, k\xe8m ti\u1ebfng Trung khi c\u1ea7n.",B.yh,B.a16,!0)
